"""Study 2 (docs/PREREGISTRATION-2.md): the decision procedure on synthetic pairs, and end to end on simulated
schedulers whose horizon and tie-break are known."""

import json
from pathlib import Path

import numpy as np
import pandas as pd

from itb_analysis import outcomes, study2
from itb_analysis.load import load_designs, load_run
from itb_analysis.sim import Params, simulate

FIXTURES = Path(__file__).resolve().parent / "fixtures"
# Generated by: itb design --study 2 --targets analysis/tests/fixtures/targets-study2.json --seed 7
#               --out analysis/tests/fixtures/design-study2.jsonl
DESIGN = FIXTURES / "design-study2.jsonl"
TARGETS = FIXTURES / "targets-study2.json"
AGAVE, FD, FD2 = ((t["identity"], t["client_id"]) for t in json.loads(TARGETS.read_text()))
PERFECT = {"p_transport_error": 0.0, "p_unproduced": 0.0, "p_transition": 0.0}


def group(t):
    return {"identity": t[0], "client_id": t[1], "ingress": "direct"}


HYPOTHESES = [
    {"id": "H1", "statement": "Agave does not overtake a 2 ms head start", "pair_kind": "race", "dt_ms": 2.0,
     "side": "less", "groups": [group(AGAVE)]},
    {"id": "H2", "statement": "Firedancer overtakes a 2 ms head start", "pair_kind": "race", "dt_ms": 2.0,
     "side": "greater", "groups": [group(FD)]},
    {"id": "H3", "statement": "Firedancer breaks equal-key ties later-arrival-first", "pair_kind": "equal_key",
     "dt_ms": 10.0, "side": "less", "groups": [group(FD), group(FD2)]},
]


def _verdicts(tmp_path, name, scenarios, **kw):
    params = Params(scenario="fifo", seed=11, landing=kw.pop("landing", 1.0), target_scenarios=scenarios, **(PERFECT | kw))
    run = load_run(simulate(DESIGN, TARGETS, tmp_path / name, params, stage=2))
    designs = load_designs([DESIGN])
    pairs = study2.pair_table(outcomes.probe_table(run), outcomes.window_table(run, designs))
    return {h["id"]: h for h in study2.evaluate(pairs, HYPOTHESES)}, pairs


def test_known_horizons_and_tie_break_are_recovered(tmp_path):
    greedy = {"scenario": "reward_cost_greedy", "pass_ms": 15.0, "tie": "lifo"}
    v, pairs = _verdicts(tmp_path, "truth", {AGAVE[0]: {"scenario": "fifo"}, FD[0]: greedy, FD2[0]: greedy})
    assert pairs["evaluable"].all()
    assert {k: h["verdict"] for k, h in v.items()} == {"H1": "supported", "H2": "supported", "H3": "supported"}
    assert all(h["selection_robust"] for h in v.values())
    assert v["H1"]["n"] == 35 and v["H3"]["n"] == 35 + 24, "every planned 2 ms head-start race and equal-key pair"


def test_the_opposite_schedulers_support_nothing(tmp_path):
    v, _ = _verdicts(tmp_path, "null", {AGAVE[0]: {"scenario": "reward_cost_greedy", "pass_ms": 15.0},
                                         FD[0]: {"scenario": "fifo"},
                                         FD2[0]: {"scenario": "reward_cost_greedy", "tie": "random"}})
    assert {h["verdict"] for h in v.values()} == {"not supported"}


def test_lost_members_weaken_but_do_not_flip_a_claim(tmp_path):
    greedy = {"scenario": "reward_cost_greedy", "pass_ms": 15.0, "tie": "lifo"}
    v, _ = _verdicts(tmp_path, "lossy", {AGAVE[0]: {"scenario": "fifo"}, FD[0]: greedy, FD2[0]: greedy}, landing=0.6)
    for h in v.values():
        assert h["incomplete_pairs"] > 0 and h["p_worst"] >= h["p"]
        assert h["verdict"] in ("supported", "not supported")


def _pairs(rows):
    base = {"run_id": "r", "client_id": "Agave", "ingress": "direct", "kind": "race", "dt_ms": 2.0, "first_label": "lo",
            "evaluable": True, "exclusion": "", "n_landed": 2, "target_identity": AGAVE[0], "achieved_gap_ms": 2.0,
            "success_censored": np.nan}
    return pd.DataFrame([base | {"pair_id": f"p{i}"} | r for i, r in enumerate(rows)])


def test_decision_rule_holm_and_selection_bound():
    rows = [{"success": 0.0}] * 30 + [{"success": np.nan, "n_landed": 1}] * 2 + [{"success": 1.0, "first_label": "hi"}] * 5
    h = [HYPOTHESES[0], HYPOTHESES[1] | {"groups": [group(AGAVE)], "id": "H2"}, HYPOTHESES[2]]
    v = {x["id"]: x for x in study2.evaluate(_pairs(rows), h)}
    assert (v["H1"]["k"], v["H1"]["n"], v["H1"]["incomplete_pairs"]) == (0, 30, 2), "hi-first races are not head starts"
    assert v["H1"]["verdict"] == "supported" and v["H1"]["selection_robust"]
    assert v["H2"]["verdict"] == "not supported"
    assert v["H3"]["verdict"] == "not evaluable" and v["H3"]["p"] == 1.0
    assert v["H1"]["p_holm"] == v["H1"]["p"] * 3, "Holm over all three, the not-evaluable one included"


def test_a_window_outside_the_frozen_group_is_not_confirmatory():
    rows = [{"success": 0.0, "client_id": "AgaveBam", "ingress": "bam_node"}] * 30
    assert study2.evaluate(_pairs(rows), HYPOTHESES[:1])[0]["verdict"] == "not evaluable"


def test_horizon_brackets():
    assert study2.horizon([(0, 3, 6), (2, 0, 36)]) == (0, 2)
    assert study2.horizon([(2, 0, 10), (5, 0, 10)]) == (None, 2)
    assert study2.horizon([(2, 9, 10), (5, 0, 0)]) == (2, None)


def test_lost_hi_first_controls_withdraw_and_a_missed_gap_flags():
    rows = [{"success": 0.0}] * 30 + [{"success": 0.0, "first_label": "hi"}] * 2 + [{"success": 1.0, "first_label": "hi"}] * 4
    pairs = _pairs(rows).assign(achieved_gap_ms=3.5)
    h = HYPOTHESES[0]
    g = study2.gates(pairs, h)
    assert (g["control_losses"], g["controls"], g["withdrawn"], g["gap_flag"]) == (2, 6, True, True)
    decided = study2.evaluate(pairs, [h])[0]
    assert study2.published(decided, g).startswith("withdrawn")
    ok = study2.gates(_pairs(rows[:-5]).assign(achieved_gap_ms=2.1), h)
    assert not ok["withdrawn"] and not ok["gap_flag"]


def test_censored_coding_scores_single_landings():
    # hi landed alone: an overtake under censored coding; lo landed alone: not.
    rows = [{"success": 0.0, "success_censored": 0.0}] * 10 + [{"success": np.nan, "n_landed": 1, "success_censored": 1.0}] * 3 \
        + [{"success": np.nan, "n_landed": 1, "success_censored": 0.0}] * 2
    cc, cens = study2.evaluate(_pairs(rows), HYPOTHESES[:1])[0], study2.evaluate(_pairs(rows), HYPOTHESES[:1], coding="censored")[0]
    assert (cc["k"], cc["n"]) == (0, 10) and (cens["k"], cens["n"]) == (3, 15)


def test_analyse_end_to_end(tmp_path):
    greedy = {"scenario": "reward_cost_greedy", "pass_ms": 15.0, "tie": "lifo"}
    params = Params(scenario="fifo", seed=3, landing=1.0, target_scenarios={AGAVE[0]: {"scenario": "fifo"}, FD[0]: greedy,
                                                                            FD2[0]: greedy}, **PERFECT)
    out = simulate(DESIGN, TARGETS, tmp_path / "e2e", params, stage=2)
    res = study2.analyse([out], {"hypotheses": HYPOTHESES}, load_designs([DESIGN]))
    assert [h["published_claim"] for h in res["hypotheses"]] == ["supported"] * 3
    assert set(res["sensitivity"]) == {"censored", "including_transition_ambiguous", "achieved_gap_within_0.5ms",
                                       "same_slot", "equal_key_both_sent_before_first_shred"}
    # The simulator writes no first-shred events, so the buffering evidence is unknown there and that set is empty.
    assert all(v["verdict"] == "supported" for k, s in res["sensitivity"].items()
               if k != "equal_key_both_sent_before_first_shred" for v in s.values())
    fd = res["curves"][f"{FD[0]}|Firedancer|direct"]
    assert fd["median_achieved_gap_ms"]["2"] == 2.0 and fd["horizon_ms"][0] is not None
    assert res["funnel"]["windows"] == res["funnel"]["evaluable"] == 35 * 2 + 24


def test_a_missed_gap_or_a_failed_control_withdraws():
    rows = [{"success": 0.0}] * 30 + [{"success": 1.0, "first_label": "hi"}] * 6
    h = HYPOTHESES[0]
    decided = study2.evaluate(_pairs(rows), [h])[0]
    assert decided["by_target"] == {AGAVE[0]: [0, 30]}
    off = study2.gates(_pairs(rows).assign(achieved_gap_ms=3.2), h)
    assert off["withdrawn"] and study2.published(decided, off).startswith("withdrawn: achieved gap 3.20 ms")
    ok = study2.gates(_pairs(rows), h)
    assert study2.published(decided, ok) == "supported"
    assert study2.published(decided, ok, method_ok=False).startswith("withdrawn: a positive control failed")


def test_replication_compares_published_claims_per_core_target():
    core = [group(AGAVE), group(FD)]
    key = lambda g: f"{g['identity']}|{g['client_id']}|{g['ingress']}"  # noqa: E731
    s1 = {"validators": {key(g): {"published_claim": "reward_cost"} for g in core}}
    s2 = {"validators": {key(core[0]): {"published_claim": "reward_cost"}, key(core[1]): {"published_claim": "partial:reward_cost"}}}
    rows = study2.replication_summary({"core_targets": core}, s1, s2)
    assert [r["replicated"] for r in rows] == [True, False]
    assert study2.replication_summary({"core_targets": core}, s1, {})[0]["replicated"] is False, "no Study 2 claim: not replicated"


def test_simultaneous_races_are_not_controls_and_count_both_orders_at_zero():
    # GPT pre-freeze finding 1: three lost hi-first races at Δt = 0 must not withdraw a 2 ms result.
    rows = [{"success": 0.0}] * 30 + [{"success": 1.0, "first_label": "hi", "dt_ms": 5.0}] * 6         + [{"success": 0.0, "first_label": "hi", "dt_ms": 0.0}] * 3 + [{"success": 1.0, "first_label": "lo", "dt_ms": 0.0}] * 3
    pairs = _pairs(rows).assign(same_slot=True)
    g = study2.gates(pairs, HYPOTHESES[0])
    assert (g["control_losses"], g["controls"], g["withdrawn"]) == (0, 6, False)
    curve = study2.curves(pairs)[f"{AGAVE[0]}|Agave|direct"]
    assert curve["overtake_lo_first"]["0"] == [3, 6], "O(0) over both stream orders, hi landing first"
    assert curve["hi_first_wins"] == {"5": [6, 6]}


def test_equal_key_gap_is_gated_too():
    rows = [{"success": 0.0, "kind": "equal_key", "dt_ms": 10.0, "first_label": "A"}] * 40
    pairs = _pairs(rows).assign(achieved_gap_ms=0.1, client_id="Firedancer", target_identity=FD[0])
    g = study2.gates(pairs, HYPOTHESES[2])
    assert g["gap_flag"] and g["withdrawn"] and g["controls"] is None
    assert study2.published(study2.evaluate(pairs, [HYPOTHESES[2]])[0], g).startswith("withdrawn: achieved gap 0.10 ms")
